# Refined transformation: add 3s only where current value equals background
def apply_transformation(grid):
    """Apply the ARC transformation seen in demo."""
    height, width = len(grid), len(grid[0])

    # Identify background color (most common color)
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    background = max(counts, key=counts.get)

    result = [row[:] for row in grid]

    # Find all "object" positions (pixels != background)
    objects = []
    for r in range(height):
        for c in range(width):
            if grid[r][c] != background:
                objects.append((r, c))

    # For each object position, place 3s in a 3x3 pattern around it
    # Only fill in cells that currently have the background color
    for r, c in objects:
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < height and 0 <= nc < width:
                    # Fill with 3 if it's background-colored
                    if result[nr][nc] == background:
                        result[nr][nc] = 3

    return result

